(last_reconcile_result IS NULL OR last_reconcile_result IN ('FOUND_EXACT','NOT_FOUND','CHECKSUM_UNAVAILABLE','CONFLICT','UNAVAILABLE','DESTINATION_CHANGED')),remote_file_id TEXT UNIQUE, remote_parent_id TEXT, remote_name_observed TEXT, remote_mime_type TEXT,remote_size INTEGER, remote_sha256 TEXT, remote_md5 TEXT, accepted_app_properties_json TEXT,verification_method TEXT CHECK(verification_method IS NULL OR verification_method IN ('SHA256','MD5_SIZE')),receipt_sha256 TEXT, verified_run_id TEXT, verified_at_utc TEXT,uncertain_at_utc TEXT, conflict_at_utc TEXT, hold_at_utc TEXT,support_ref TEXT CHECK(support_ref IS NULL OR (length(support_ref) BETWEEN 4 AND 63 AND substr(support_ref,1,3)='EG_' AND substr(support_ref,4) NOT GLOB '*[^A-Z0-9_]*')),UNIQUE(invoice_id,binding_id), UNIQUE(binding_id,remote_name),CHECK((reserved_remote_file_id IS NULL AND reserved_run_id IS NULL AND reserved_at_utc IS NULL) OR (reserved_remote_file_id IS NOT NULL AND reserved_run_id IS NOT NULL AND reserved_at_utc IS NOT NULL)),CHECK(upload_attempt_count=0 OR reserved_remote_file_id IS NOT NULL),CHECK((retry_authorised_run_id IS NULL)=(retry_authorised_at_utc IS NULL)),CHECK(retry_authorised_run_id IS NULL OR upload_attempt_count>=1),CHECK(state!='DRIVE_VERIFIED' OR (upload_attempt_count>=1 AND remote_file_id IS NOT NULL AND remote_file_id=reserved_remote_file_id AND remote_parent_id=folder_id AND remote_name_observed=remote_name AND remote_mime_type='application/pdf' AND typeof(remote_size)='integer' AND remote_size=local_byte_size AND accepted_app_properties_json=app_properties_json AND (remote_sha256 IS NULL OR remote_sha256=local_sha256) AND (remote_md5 IS NULL OR remote_md5=local_md5) AND ((verification_method='SHA256' AND remote_sha256=local_sha256) OR (verification_method='MD5_SIZE' AND remote_sha256 IS NULL AND remote_md5=local_md5)) AND length(receipt_sha256)=64 AND receipt_sha256 NOT GLOB '*[^0-9a-f]*' AND verified_run_id IS NOT NULL AND verified_at_utc IS NOT NULL)),CHECK(state='DRIVE_VERIFIED' OR (remote_file_id IS NULL AND remote_parent_id IS NULL AND remote_name_observed IS NULL AND remote_mime_type IS NULL AND remote_size IS NULL AND remote_sha256 IS NULL AND remote_md5 IS NULL AND accepted_app_properties_json IS NULL AND verification_method IS NULL AND receipt_sha256 IS NULL AND verified_run_id IS NULL AND verified_at_utc IS NULL)),CHECK(state!='DRIVE_UPLOAD_UNCERTAIN' OR uncertain_at_utc IS NOT NULL),CHECK(state!='DRIVE_CONFLICT' OR (conflict_at_utc IS NOT NULL AND support_ref IS NOT NULL)),CHECK(state!='HOLD' OR (hold_at_utc IS NOT NULL AND support_ref IS NOT NULL))) STRICT;
CREATE TABLE energygrid_file_operation_v2 (operation_id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES energygrid_invoice_v2(invoice_id),kind TEXT NOT NULL CHECK(kind IN ('ARCHIVE_PUBLISH','LEGACY_MOVE','DRIVE_STAGE')),state TEXT NOT NULL CHECK(state IN ('PREPARED','COMMITTED','HOLD')),private_path_ref TEXT NOT NULL, target_relpath TEXT NOT NULL, binding_id TEXT,expected_size INTEGER NOT NULL CHECK(typeof(expected_size)='integer' AND expected_size>0),expected_sha256 TEXT NOT NULL CHECK(length(expected_sha256)=64 AND expected_sha256 NOT GLOB '*[^0-9a-f]*'), source_role TEXT NOT NULL,run_id TEXT NOT NULL, prepared_at_utc TEXT NOT NULL, committed_at_utc TEXT, evidence_ref TEXT, support_ref TEXT,CHECK((state='PREPARED' AND committed_at_utc IS NULL AND evidence_ref IS NULL AND support_ref IS NULL) OR (state='COMMITTED' AND committed_at_utc IS NOT NULL AND evidence_ref IS NOT NULL AND support_ref IS NULL) OR (state='HOLD' AND committed_at_utc IS NULL AND evidence_ref IS NULL AND support_ref IS NOT NULL))) STRICT;
CREATE TABLE energygrid_invoice_v2 (invoice_id TEXT PRIMARY KEY,legacy_filename_key TEXT UNIQUE REFERENCES bills(filename_key),classification TEXT NOT NULL CHECK(classification IN ('UNCLASSIFIED','CLASSIFIED')),stream TEXT REFERENCES energygrid_stream_v2(stream),source_namespace TEXT, source_invoice_key TEXT, source_filename TEXT, raw_date TEXT,date_profile TEXT, bill_date TEXT, day_ordinal INTEGER, evidence_ref TEXT,canonical_filename TEXT, archive_relpath TEXT, legacy_path TEXT,archive_state TEXT NOT NULL CHECK(archive_state IN ('UNVERIFIED','ABSENT','PREPARED','COMMITTED','CONFLICT')),byte_size INTEGER, sha256 TEXT, archived_at_utc TEXT,migration_state TEXT NOT NULL CHECK(migration_state IN ('UNCLASSIFIED','CLASSIFIED','MOVE_PLANNED','COMPLETE','HOLD','NOT_REQUIRED')),drive_state TEXT NOT NULL CHECK(drive_state IN ('NOT_STAGED','PREPARED','DRIVE_STAGED','CONFLICT')),drive_binding_id TEXT, drive_relpath TEXT, drive_size INTEGER, drive_sha256 TEXT, drive_staged_at_utc TEXT,created_at_utc TEXT NOT NULL, created_run_id TEXT NOT NULL, last_seen_run_id TEXT,CHECK((classification='UNCLASSIFIED' AND stream IS NULL AND source_namespace IS NULL AND source_invoice_key IS NULL AND source_filename IS NULL AND raw_date IS NULL AND date_profile IS NULL AND bill_date IS NULL AND day_ordinal IS NULL AND evidence_ref IS NULL AND canonical_filename IS NULL AND archive_relpath IS NULL) OR (classification='CLASSIFIED' AND stream IS NOT NULL AND source_namespace IS NOT NULL AND source_invoice_key IS NOT NULL AND source_filename IS NOT NULL AND raw_date IS NOT NULL AND date_profile='INVOICE_DATE_ISO_V1' AND bill_date IS NOT NULL AND day_ordinal BETWEEN 1 AND 3652059 AND evidence_ref IS NOT NULL AND canonical_filename=bill_date||'.pdf' AND archive_relpath IS NOT NULL)),CHECK(classification!='CLASSIFIED' OR archive_relpath=(CASE stream WHEN 'EB_BILL' THEN 'EB Bill/' ELSE 'Tenant Bill/' END)||canonical_filename),CHECK(archive_state!='COMMITTED' OR (classification='CLASSIFIED' AND archive_relpath IS NOT NULL AND byte_size>0 AND length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*' AND archived_at_utc IS NOT NULL)),CHECK(drive_state!='DRIVE_STAGED' OR (classification='CLASSIFIED' AND drive_binding_id IS NOT NULL AND drive_relpath=archive_relpath AND drive_size=byte_size AND drive_sha256=sha256 AND drive_staged_at_utc IS NOT NULL)),CHECK(byte_size IS NULL OR (typeof(byte_size)='integer' AND byte_size>0)),CHECK(drive_size IS NULL OR (typeof(drive_size)='integer' AND drive_size>0))) STRICT;
CREATE TABLE energygrid_run_stream_stop_v3 (run_id TEXT NOT NULL REFERENCES energygrid_run_v3(run_id),stream TEXT NOT NULL CHECK(stream IN ('EB_BILL','TENANT_BILL')),command TEXT NOT NULL CHECK(command IN ('drive-intent','drive-upload','drive-reconcile','deliver')),outcome TEXT NOT NULL CHECK(outcome IN ('HOLD','DRIVE_CONFLICT','DRIVE_UPLOAD_UNCERTAIN','RESERVATION_UNAVAILABLE','DELIVERY_OUTCOME_UNCERTAIN','REQUEST_REJECTED')),exit_code INTEGER NOT NULL CHECK(typeof(exit_code)='integer' AND exit_code IN (10,20)),support_ref TEXT CHECK(support_ref IS NULL OR (length(support_ref) BETWEEN 4 AND 63 AND substr(support_ref,1,3)='EG_' AND substr(support_ref,4) NOT GLOB '*[^A-Z0-9_]*')),stopped_at_utc TEXT NOT NULL,PRIMARY KEY(run_id,stream)) STRICT;
CREATE TABLE energygrid_run_v3 (run_id TEXT PRIMARY KEY CHECK(length(run_id)=36 AND run_id NOT GLOB '*[^0-9a-f-]*'),started_at_utc TEXT NOT NULL,acquire_state TEXT NOT NULL CHECK(acquire_state IN ('COMPLETED','FAILED')),acquire_at_utc TEXT NOT NULL,acquire_exit_code INTEGER NOT NULL CHECK(typeof(acquire_exit_code)='integer' AND acquire_exit_code BETWEEN 0 AND 255),acquire_support_ref TEXT,eb_bill_acquire TEXT NOT NULL CHECK(eb_bill_acquire IN ('READY','EMPTY','UNBOUND','HOLD','SOURCE_FAILURE','SOURCE_FAILURE_RETRYABLE','NOT_REACHED')),tenant_bill_acquire TEXT NOT NULL CHECK(tenant_bill_acquire IN ('READY','EMPTY','UNBOUND','HOLD','SOURCE_FAILURE','SOURCE_FAILURE_RETRYABLE','NOT_REACHED')),eb_bill_support_ref TEXT, tenant_bill_support_ref TEXT,CHECK((acquire_state='COMPLETED')=(acquire_exit_code=0))) STRICT;
CREATE TABLE energygrid_stream_v2 (stream TEXT PRIMARY KEY CHECK(stream IN ('EB_BILL','TENANT_BILL')),source_namespace TEXT, adapter_id TEXT, date_profile TEXT, evidence_ref TEXT,admission TEXT NOT NULL CHECK(admission IN ('UNBOUND','BOUND','HOLD')),watermark_day INTEGER, watermark_invoice_id TEXT REFERENCES energygrid_invoice_v2(invoice_id),watermark_run_id TEXT, watermark_at_utc TEXT,CHECK((admission='UNBOUND' AND source_namespace IS NULL AND adapter_id IS NULL AND date_profile IS NULL AND evidence_ref IS NULL) OR (admission='BOUND' AND source_namespace IS NOT NULL AND adapter_id='DIRECT_HTTP_V1' AND date_profile='INVOICE_DATE_ISO_V1' AND evidence_ref IS NOT NULL) OR admission='HOLD'),CHECK((watermark_day IS NULL AND watermark_invoice_id IS NULL AND watermark_run_id IS NULL AND watermark_at_utc IS NULL) OR (watermark_day BETWEEN 1 AND 3652059 AND watermark_invoice_id IS NOT NULL AND watermark_run_id IS NOT NULL AND watermark_at_utc IS NOT NULL))) STRICT;
