CREATE UNIQUE INDEX energygrid_invoice_identity_v2 ON energygrid_invoice_v2(source_namespace,stream,source_invoice_key) WHERE classification='CLASSIFIED';
CREATE UNIQUE INDEX energygrid_invoice_archive_relpath_v2 ON energygrid_invoice_v2(archive_relpath) WHERE classification='CLASSIFIED';
CREATE UNIQUE INDEX energygrid_invoice_drive_path_v2 ON energygrid_invoice_v2(drive_binding_id,drive_relpath) WHERE drive_state='DRIVE_STAGED';
CREATE UNIQUE INDEX energygrid_file_operation_prepared_v2 ON energygrid_file_operation_v2(invoice_id,kind,ifnull(binding_id,''),target_relpath) WHERE state IN ('PREPARED','HOLD');
CREATE TRIGGER energygrid_stream_watermark_guard_v2 BEFORE UPDATE OF watermark_day,watermark_invoice_id,watermark_run_id,watermark_at_utc ON energygrid_stream_v2 BEGIN SELECT CASE WHEN OLD.watermark_day IS NOT NULL AND (NEW.watermark_day IS NULL OR NEW.watermark_day<OLD.watermark_day) THEN RAISE(ABORT,'watermark regression') END; SELECT CASE WHEN OLD.watermark_day=NEW.watermark_day AND OLD.watermark_invoice_id IS NOT NEW.watermark_invoice_id THEN RAISE(ABORT,'watermark identity conflict') END; SELECT CASE WHEN NEW.watermark_day IS NOT NULL AND NOT EXISTS (SELECT 1 FROM energygrid_invoice_v2 i WHERE i.invoice_id=NEW.watermark_invoice_id AND i.classification='CLASSIFIED' AND i.stream=NEW.stream AND i.source_namespace=NEW.source_namespace AND i.day_ordinal=NEW.watermark_day) THEN RAISE(ABORT,'watermark invoice mismatch') END; END;
CREATE TRIGGER energygrid_invoice_binding_insert_guard_v2 BEFORE INSERT ON energygrid_invoice_v2 WHEN NEW.classification='CLASSIFIED' AND NOT EXISTS (SELECT 1 FROM energygrid_stream_v2 s WHERE s.stream=NEW.stream AND s.admission='BOUND' AND s.source_namespace=NEW.source_namespace AND s.date_profile=NEW.date_profile AND s.evidence_ref=NEW.evidence_ref) BEGIN SELECT RAISE(ABORT,'invoice stream binding mismatch'); END;
CREATE TRIGGER energygrid_invoice_binding_update_guard_v2 BEFORE UPDATE OF classification,stream,source_namespace,date_profile,evidence_ref ON energygrid_invoice_v2 WHEN OLD.classification='UNCLASSIFIED' AND NEW.classification='CLASSIFIED' AND NOT EXISTS (SELECT 1 FROM energygrid_stream_v2 s WHERE s.stream=NEW.stream AND s.admission='BOUND' AND s.source_namespace=NEW.source_namespace AND s.date_profile=NEW.date_profile AND s.evidence_ref=NEW.evidence_ref) BEGIN SELECT RAISE(ABORT,'invoice stream binding mismatch'); END;
CREATE TRIGGER energygrid_invoice_no_delete_v2 BEFORE DELETE ON energygrid_invoice_v2 BEGIN SELECT RAISE(ABORT,'invoice rows are retained'); END;
CREATE TRIGGER energygrid_invoice_archive_commit_guard_v2 BEFORE UPDATE OF archive_state ON energygrid_invoice_v2 WHEN NEW.archive_state='COMMITTED' AND OLD.archive_state!='COMMITTED' AND NOT EXISTS (SELECT 1 FROM energygrid_file_operation_v2 o WHERE o.invoice_id=NEW.invoice_id AND o.kind IN ('ARCHIVE_PUBLISH','LEGACY_MOVE') AND o.state='COMMITTED' AND o.target_relpath=NEW.archive_relpath AND o.expected_size=NEW.byte_size AND o.expected_sha256=NEW.sha256) BEGIN SELECT RAISE(ABORT,'archive commit lacks matching journal'); END;
CREATE TRIGGER energygrid_invoice_drive_commit_guard_v2 BEFORE UPDATE OF drive_state ON energygrid_invoice_v2 WHEN NEW.drive_state='DRIVE_STAGED' AND OLD.drive_state!='DRIVE_STAGED' AND NOT EXISTS (SELECT 1 FROM energygrid_file_operation_v2 o WHERE o.invoice_id=NEW.invoice_id AND o.kind='DRIVE_STAGE' AND o.state='COMMITTED' AND o.binding_id=NEW.drive_binding_id AND o.target_relpath=NEW.drive_relpath AND o.expected_size=NEW.drive_size AND o.expected_sha256=NEW.drive_sha256) BEGIN SELECT RAISE(ABORT,'Drive stage lacks matching journal'); END;
CREATE TRIGGER energygrid_invoice_identity_freeze_v2 BEFORE UPDATE ON energygrid_invoice_v2 WHEN OLD.classification='CLASSIFIED' AND (NEW.classification IS NOT OLD.classification OR NEW.stream IS NOT OLD.stream OR NEW.source_namespace IS NOT OLD.source_namespace OR NEW.source_invoice_key IS NOT OLD.source_invoice_key OR NEW.source_filename IS NOT OLD.source_filename OR NEW.raw_date IS NOT OLD.raw_date OR NEW.date_profile IS NOT OLD.date_profile OR NEW.bill_date IS NOT OLD.bill_date OR NEW.day_ordinal IS NOT OLD.day_ordinal OR NEW.evidence_ref IS NOT OLD.evidence_ref OR NEW.canonical_filename IS NOT OLD.canonical_filename OR NEW.archive_relpath IS NOT OLD.archive_relpath) BEGIN SELECT RAISE(ABORT,'classified invoice identity is frozen'); END;
CREATE TRIGGER energygrid_invoice_archive_freeze_v2 BEFORE UPDATE OF archive_state,byte_size,sha256,archived_at_utc ON energygrid_invoice_v2 WHEN OLD.archive_state='COMMITTED' AND (NEW.archive_state IS NOT OLD.archive_state OR NEW.byte_size IS NOT OLD.byte_size OR NEW.sha256 IS NOT OLD.sha256 OR NEW.archived_at_utc IS NOT OLD.archived_at_utc) BEGIN SELECT RAISE(ABORT,'committed archive facts are frozen'); END;
CREATE TRIGGER energygrid_invoice_drive_freeze_v2 BEFORE UPDATE OF drive_state,drive_binding_id,drive_relpath,drive_size,drive_sha256,drive_staged_at_utc ON energygrid_invoice_v2 WHEN OLD.drive_state='DRIVE_STAGED' AND (NEW.drive_state IS NOT OLD.drive_state OR NEW.drive_binding_id IS NOT OLD.drive_binding_id OR NEW.drive_relpath IS NOT OLD.drive_relpath OR NEW.drive_size IS NOT OLD.drive_size OR NEW.drive_sha256 IS NOT OLD.drive_sha256 OR NEW.drive_staged_at_utc IS NOT OLD.drive_staged_at_utc) BEGIN SELECT RAISE(ABORT,'staged Drive facts are frozen'); END;
CREATE TRIGGER energygrid_stream_binding_freeze_v2 BEFORE UPDATE OF source_namespace,adapter_id,date_profile,evidence_ref,admission ON energygrid_stream_v2 WHEN OLD.admission='BOUND' AND (NEW.source_namespace IS NOT OLD.source_namespace OR NEW.adapter_id IS NOT OLD.adapter_id OR NEW.date_profile IS NOT OLD.date_profile OR NEW.evidence_ref IS NOT OLD.evidence_ref OR NEW.admission IS NOT OLD.admission) AND NOT (NEW.admission='HOLD' AND NEW.source_namespace IS OLD.source_namespace AND NEW.adapter_id IS OLD.adapter_id AND NEW.date_profile IS OLD.date_profile AND NEW.evidence_ref IS OLD.evidence_ref) BEGIN SELECT RAISE(ABORT,'stream binding requires migration'); END;
CREATE TRIGGER energygrid_stream_no_delete_v2 BEFORE DELETE ON energygrid_stream_v2 BEGIN SELECT RAISE(ABORT,'stream rows are retained'); END;
CREATE TRIGGER energygrid_delivery_freeze_v1 BEFORE UPDATE ON energygrid_delivery_v1 WHEN NEW.delivery_id!=OLD.delivery_id OR NEW.invoice_id!=OLD.invoice_id OR NEW.schema!=OLD.schema OR NEW.stream!=OLD.stream OR NEW.bill_date!=OLD.bill_date OR NEW.attachment_name!=OLD.attachment_name OR NEW.sha256!=OLD.sha256 OR NEW.byte_size!=OLD.byte_size OR OLD.state!='PENDING_SEND' BEGIN SELECT RAISE(ABORT,'delivery facts are frozen'); END;
CREATE TRIGGER energygrid_delivery_marker_once_v1 BEFORE UPDATE OF dispatch_started_at_utc,dispatch_run_id ON energygrid_delivery_v1 WHEN OLD.dispatch_started_at_utc IS NOT NULL OR (NEW.dispatch_started_at_utc IS NULL)!=(NEW.dispatch_run_id IS NULL) BEGIN SELECT RAISE(ABORT,'dispatch marker is write-once'); END;
CREATE TRIGGER energygrid_delivery_no_delete_v1 BEFORE DELETE ON energygrid_delivery_v1 BEGIN SELECT RAISE(ABORT,'delivery rows are retained'); END;
CREATE TRIGGER energygrid_file_operation_plan_freeze_v2 BEFORE UPDATE ON energygrid_file_operation_v2 WHEN NEW.operation_id!=OLD.operation_id OR NEW.invoice_id!=OLD.invoice_id OR NEW.kind!=OLD.kind OR NEW.private_path_ref!=OLD.private_path_ref OR NEW.target_relpath!=OLD.target_relpath OR NEW.binding_id IS NOT OLD.binding_id OR NEW.expected_size!=OLD.expected_size OR NEW.expected_sha256!=OLD.expected_sha256 OR NEW.source_role!=OLD.source_role OR NEW.run_id!=OLD.run_id OR NEW.prepared_at_utc!=OLD.prepared_at_utc BEGIN SELECT RAISE(ABORT,'file operation plan is frozen'); END;
CREATE TRIGGER energygrid_file_operation_state_guard_v2 BEFORE UPDATE ON energygrid_file_operation_v2 WHEN OLD.state IN ('COMMITTED','HOLD') OR (OLD.state='PREPARED' AND NEW.state NOT IN ('PREPARED','COMMITTED','HOLD')) BEGIN SELECT RAISE(ABORT,'file operation state is terminal'); END;
CREATE TRIGGER energygrid_file_operation_no_delete_v2 BEFORE DELETE ON energygrid_file_operation_v2 BEGIN SELECT RAISE(ABORT,'file operation rows are retained'); END;
CREATE TRIGGER energygrid_bills_no_update_v2 BEFORE UPDATE ON bills BEGIN SELECT RAISE(ABORT,'legacy bills are immutable after v2 migration'); END;
CREATE TRIGGER energygrid_bills_no_delete_v2 BEFORE DELETE ON bills BEGIN SELECT RAISE(ABORT,'legacy bills are immutable after v2 migration'); END;
CREATE UNIQUE INDEX energygrid_drive_binding_active_v3 ON energygrid_drive_binding_v3(stream) WHERE state='ACTIVE';
CREATE TRIGGER energygrid_drive_binding_insert_guard_v3 BEFORE INSERT ON energygrid_drive_binding_v3 WHEN NEW.state!='ACTIVE' BEGIN SELECT RAISE(ABORT,'Drive binding must be inserted active'); END;
CREATE TRIGGER energygrid_drive_binding_freeze_v3 BEFORE UPDATE ON energygrid_drive_binding_v3 WHEN NOT (OLD.state='ACTIVE' AND NEW.state='RETIRED' AND NEW.retired_at_utc IS NOT NULL AND NEW.binding_id=OLD.binding_id AND NEW.stream=OLD.stream AND NEW.account_ref=OLD.account_ref AND NEW.root_folder_id=OLD.root_folder_id AND NEW.folder_id=OLD.folder_id AND NEW.logical_path=OLD.logical_path AND NEW.chain_sha256=OLD.chain_sha256 AND NEW.bound_run_id=OLD.bound_run_id AND NEW.bound_at_utc=OLD.bound_at_utc) OR EXISTS (SELECT 1 FROM energygrid_drive_operation_v3 o WHERE o.binding_id=OLD.binding_id AND o.state IN ('DRIVE_UPLOAD_INTENT','DRIVE_UPLOAD_UNCERTAIN')) BEGIN SELECT RAISE(ABORT,'Drive binding is frozen'); END;
CREATE TRIGGER energygrid_drive_binding_no_delete_v3 BEFORE DELETE ON energygrid_drive_binding_v3 BEGIN SELECT RAISE(ABORT,'Drive binding rows are retained'); END;
CREATE TRIGGER energygrid_drive_operation_insert_guard_v3 BEFORE INSERT ON energygrid_drive_operation_v3 WHEN NEW.state!='DRIVE_UPLOAD_INTENT' OR NEW.upload_attempt_count!=0 OR NEW.reserved_remote_file_id IS NOT NULL OR NEW.retry_authorised_run_id IS NOT NULL OR NEW.last_reconcile_run_id IS NOT NULL OR NEW.support_ref IS NOT NULL OR NEW.uncertain_at_utc IS NOT NULL OR NEW.conflict_at_utc IS NOT NULL OR NEW.hold_at_utc IS NOT NULL OR NOT EXISTS (SELECT 1 FROM energygrid_invoice_v2 i JOIN energygrid_stream_v2 s ON s.stream=i.stream AND s.watermark_invoice_id=i.invoice_id WHERE i.invoice_id=NEW.invoice_id AND i.classification='CLASSIFIED' AND i.stream=NEW.stream AND i.archive_state='COMMITTED' AND i.byte_size=NEW.local_byte_size AND i.sha256=NEW.local_sha256 AND i.archive_relpath=NEW.logical_relpath AND i.canonical_filename=NEW.remote_name) OR NOT EXISTS (SELECT 1 FROM energygrid_drive_binding_v3 b WHERE b.binding_id=NEW.binding_id AND b.state='ACTIVE' AND b.stream=NEW.stream AND b.folder_id=NEW.folder_id) BEGIN SELECT RAISE(ABORT,'Drive intent facts mismatch'); END;
CREATE TRIGGER energygrid_drive_operation_identity_freeze_v3 BEFORE UPDATE ON energygrid_drive_operation_v3 WHEN NEW.operation_id IS NOT OLD.operation_id OR NEW.invoice_id IS NOT OLD.invoice_id OR NEW.binding_id IS NOT OLD.binding_id OR NEW.stream IS NOT OLD.stream OR NEW.folder_id IS NOT OLD.folder_id OR NEW.logical_relpath IS NOT OLD.logical_relpath OR NEW.remote_name IS NOT OLD.remote_name OR NEW.local_byte_size IS NOT OLD.local_byte_size OR NEW.local_sha256 IS NOT OLD.local_sha256 OR NEW.local_md5 IS NOT OLD.local_md5 OR NEW.app_properties_json IS NOT OLD.app_properties_json OR NEW.intent_run_id IS NOT OLD.intent_run_id OR NEW.intent_at_utc IS NOT OLD.intent_at_utc BEGIN SELECT RAISE(ABORT,'Drive operation identity is frozen'); END;
CREATE TRIGGER energygrid_drive_operation_reservation_once_v3 BEFORE UPDATE ON energygrid_drive_operation_v3 WHEN (OLD.reserved_remote_file_id IS NOT NULL AND (NEW.reserved_remote_file_id IS NOT OLD.reserved_remote_file_id OR NEW.reserved_run_id IS NOT OLD.reserved_run_id OR NEW.reserved_at_utc IS NOT OLD.reserved_at_utc)) OR (OLD.reserved_remote_file_id IS NULL AND NEW.reserved_remote_file_id IS NOT NULL AND (OLD.state!='DRIVE_UPLOAD_INTENT' OR NEW.state!='DRIVE_UPLOAD_INTENT' OR OLD.upload_attempt_count!=0 OR NEW.upload_attempt_count!=0 OR EXISTS (SELECT 1 FROM energygrid_drive_dispatch_v3 d WHERE d.operation_id=OLD.operation_id))) OR (OLD.reserved_remote_file_id IS NULL AND NEW.reserved_remote_file_id IS NULL AND (NEW.reserved_run_id IS NOT NULL OR NEW.reserved_at_utc IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'reserved Drive file ID is frozen'); END;
CREATE TRIGGER energygrid_drive_operation_attempt_guard_v3 BEFORE UPDATE OF upload_attempt_count ON energygrid_drive_operation_v3 WHEN NEW.upload_attempt_count IS NOT OLD.upload_attempt_count AND (NEW.upload_attempt_count!=OLD.upload_attempt_count+1 OR OLD.state!='DRIVE_UPLOAD_INTENT' OR NEW.state!='DRIVE_UPLOAD_INTENT' OR NOT EXISTS (SELECT 1 FROM energygrid_drive_dispatch_v3 d WHERE d.operation_id=OLD.operation_id AND d.attempt_no=NEW.upload_attempt_count AND d.reserved_remote_file_id=OLD.reserved_remote_file_id)) BEGIN SELECT RAISE(ABORT,'Drive attempt count requires a dispatch marker'); END;
CREATE TRIGGER energygrid_drive_operation_terminal_freeze_v3 BEFORE UPDATE ON energygrid_drive_operation_v3 WHEN OLD.state IN ('DRIVE_VERIFIED','DRIVE_CONFLICT') OR (OLD.state='HOLD' AND OLD.support_ref!='EG_DRIVE_VERIFICATION_UNAVAILABLE') BEGIN SELECT RAISE(ABORT,'terminal Drive operation is frozen'); END;
CREATE TRIGGER energygrid_drive_operation_state_guard_v3 BEFORE UPDATE OF state ON energygrid_drive_operation_v3 WHEN NEW.state IS NOT OLD.state AND NOT ((OLD.state='DRIVE_UPLOAD_INTENT' AND NEW.state IN ('DRIVE_VERIFIED','DRIVE_UPLOAD_UNCERTAIN','DRIVE_CONFLICT','HOLD')) OR (OLD.state='DRIVE_UPLOAD_UNCERTAIN' AND NEW.state IN ('DRIVE_VERIFIED','DRIVE_CONFLICT','HOLD')) OR (OLD.state='DRIVE_UPLOAD_UNCERTAIN' AND NEW.state='DRIVE_UPLOAD_INTENT' AND OLD.upload_attempt_count=1 AND NEW.upload_attempt_count=1  AND OLD.retry_authorised_run_id IS NULL AND NEW.retry_authorised_run_id IS NOT NULL AND NEW.retry_authorised_run_id=NEW.last_reconcile_run_id  AND NEW.last_reconcile_result='NOT_FOUND'  AND NOT EXISTS (SELECT 1 FROM energygrid_drive_dispatch_v3 d WHERE d.operation_id=OLD.operation_id AND (d.outcome IS NULL OR d.dispatch_run_id=NEW.retry_authorised_run_id))) OR (OLD.state='HOLD' AND OLD.support_ref='EG_DRIVE_VERIFICATION_UNAVAILABLE' AND NEW.state='DRIVE_VERIFIED')) BEGIN SELECT RAISE(ABORT,'Drive state transition is not allowed'); END;
CREATE TRIGGER energygrid_drive_operation_retry_once_v3 BEFORE UPDATE OF retry_authorised_run_id,retry_authorised_at_utc ON energygrid_drive_operation_v3 WHEN (OLD.retry_authorised_run_id IS NOT NULL AND (NEW.retry_authorised_run_id IS NOT OLD.retry_authorised_run_id OR NEW.retry_authorised_at_utc IS NOT OLD.retry_authorised_at_utc)) OR (OLD.retry_authorised_run_id IS NULL AND NEW.retry_authorised_run_id IS NOT NULL AND NOT (OLD.state='DRIVE_UPLOAD_UNCERTAIN' AND NEW.state='DRIVE_UPLOAD_INTENT')) BEGIN SELECT RAISE(ABORT,'Drive retry authority is write-once'); END;
CREATE TRIGGER energygrid_drive_operation_verified_binding_v3 BEFORE UPDATE OF state ON energygrid_drive_operation_v3 WHEN NEW.state='DRIVE_VERIFIED' AND OLD.state!='DRIVE_VERIFIED' AND (NOT EXISTS (SELECT 1 FROM energygrid_drive_binding_v3 b WHERE b.binding_id=NEW.binding_id AND b.state='ACTIVE' AND b.folder_id=NEW.folder_id) OR EXISTS (SELECT 1 FROM energygrid_drive_dispatch_v3 d WHERE d.operation_id=NEW.operation_id AND (d.outcome IS NULL OR d.reserved_remote_file_id IS NOT NEW.reserved_remote_file_id)) OR NOT EXISTS (SELECT 1 FROM energygrid_invoice_v2 i WHERE i.invoice_id=NEW.invoice_id AND i.archive_state='COMMITTED' AND i.byte_size=NEW.local_byte_size AND i.sha256=NEW.local_sha256)) BEGIN SELECT RAISE(ABORT,'Drive verification lacks current authority'); END;
CREATE TRIGGER energygrid_drive_operation_no_delete_v3 BEFORE DELETE ON energygrid_drive_operation_v3 BEGIN SELECT RAISE(ABORT,'Drive operation rows are retained'); END;
CREATE TRIGGER energygrid_drive_dispatch_insert_guard_v3 BEFORE INSERT ON energygrid_drive_dispatch_v3 WHEN NEW.outcome IS NOT NULL OR NOT EXISTS (SELECT 1 FROM energygrid_drive_operation_v3 o WHERE o.operation_id=NEW.operation_id AND o.state='DRIVE_UPLOAD_INTENT' AND o.reserved_remote_file_id IS NOT NULL AND o.reserved_remote_file_id=NEW.reserved_remote_file_id AND NEW.attempt_no=o.upload_attempt_count+1 AND (NEW.attempt_no=1 OR (o.retry_authorised_run_id IS NOT NULL AND o.last_reconcile_run_id=NEW.dispatch_run_id AND o.last_reconcile_result='NOT_FOUND'))) OR EXISTS (SELECT 1 FROM energygrid_drive_dispatch_v3 d WHERE d.operation_id=NEW.operation_id AND (d.outcome IS NULL OR d.dispatch_run_id=NEW.dispatch_run_id)) BEGIN SELECT RAISE(ABORT,'Drive dispatch is not authorised'); END;
CREATE TRIGGER energygrid_drive_dispatch_once_v3 BEFORE UPDATE ON energygrid_drive_dispatch_v3 WHEN OLD.outcome IS NOT NULL OR NEW.operation_id IS NOT OLD.operation_id OR NEW.attempt_no IS NOT OLD.attempt_no OR NEW.reserved_remote_file_id IS NOT OLD.reserved_remote_file_id OR NEW.dispatch_run_id IS NOT OLD.dispatch_run_id OR NEW.dispatched_at_utc IS NOT OLD.dispatched_at_utc BEGIN SELECT RAISE(ABORT,'Drive dispatch marker is write-once'); END;
CREATE TRIGGER energygrid_drive_dispatch_no_delete_v3 BEFORE DELETE ON energygrid_drive_dispatch_v3 BEGIN SELECT RAISE(ABORT,'Drive dispatch rows are retained'); END;
CREATE TRIGGER energygrid_run_no_update_v3 BEFORE UPDATE ON energygrid_run_v3 BEGIN SELECT RAISE(ABORT,'run rows are insert-only'); END;
CREATE TRIGGER energygrid_run_no_delete_v3 BEFORE DELETE ON energygrid_run_v3 BEGIN SELECT RAISE(ABORT,'run rows are retained'); END;
CREATE TRIGGER energygrid_run_stream_stop_no_update_v3 BEFORE UPDATE ON energygrid_run_stream_stop_v3 BEGIN SELECT RAISE(ABORT,'run stream stop rows are insert-only'); END;
CREATE TRIGGER energygrid_run_stream_stop_no_delete_v3 BEFORE DELETE ON energygrid_run_stream_stop_v3 BEGIN SELECT RAISE(ABORT,'run stream stop rows are retained'); END;
CREATE TRIGGER energygrid_invoice_drive_legacy_freeze_v3 BEFORE UPDATE ON energygrid_invoice_v2 WHEN NEW.drive_state IS NOT OLD.drive_state OR NEW.drive_binding_id IS NOT OLD.drive_binding_id OR NEW.drive_relpath IS NOT OLD.drive_relpath OR NEW.drive_size IS NOT OLD.drive_size OR NEW.drive_sha256 IS NOT OLD.drive_sha256 OR NEW.drive_staged_at_utc IS NOT OLD.drive_staged_at_utc BEGIN SELECT RAISE(ABORT,'historical Drive stage facts are frozen'); END;
CREATE TRIGGER energygrid_invoice_drive_legacy_insert_guard_v3 BEFORE INSERT ON energygrid_invoice_v2 WHEN NEW.drive_state!='NOT_STAGED' OR NEW.drive_binding_id IS NOT NULL OR NEW.drive_relpath IS NOT NULL OR NEW.drive_size IS NOT NULL OR NEW.drive_sha256 IS NOT NULL OR NEW.drive_staged_at_utc IS NOT NULL BEGIN SELECT RAISE(ABORT,'filesystem Drive staging is retired'); END;
CREATE TRIGGER energygrid_file_operation_drive_stage_retired_v3 BEFORE INSERT ON energygrid_file_operation_v2 WHEN NEW.kind='DRIVE_STAGE' BEGIN SELECT RAISE(ABORT,'filesystem Drive staging is retired'); END;
CREATE TRIGGER energygrid_delivery_invoice_guard_v3 BEFORE INSERT ON energygrid_delivery_v1 WHEN NOT EXISTS (SELECT 1 FROM energygrid_invoice_v2 i WHERE i.invoice_id=NEW.invoice_id AND i.classification='CLASSIFIED' AND i.stream=NEW.stream AND i.bill_date=NEW.bill_date AND i.canonical_filename=NEW.attachment_name AND i.archive_state='COMMITTED' AND i.byte_size=NEW.byte_size AND i.sha256=NEW.sha256) OR NOT EXISTS (SELECT 1 FROM energygrid_drive_operation_v3 o JOIN energygrid_drive_binding_v3 b ON b.binding_id=o.binding_id WHERE o.invoice_id=NEW.invoice_id AND o.state='DRIVE_VERIFIED' AND o.local_sha256=NEW.sha256 AND o.local_byte_size=NEW.byte_size AND o.remote_file_id=o.reserved_remote_file_id AND b.state='ACTIVE' AND b.stream=NEW.stream) BEGIN SELECT RAISE(ABORT,'delivery requires a verified Drive receipt'); END;
COMMIT;
PRAGMA user_version=3;
